ProjectALife.DialogueShards["scenes_misc_2"] = {
{"exp_civ_lost_subject","awkward_chat",2,"reg=civilian|st=friendly,neutral,careful",{1,"Uhhh--... So? Where was I?",2,"Your neighbor, the mower thing",1,"OHHH - YEAH",1,"Six in the goddamn morning - every Saturday",2,"I'd take that noise back",1,"Yeah, yeah, so would I"}},
{"s13_law_badge_drawer_004","badge",1,"reg=law|tmp=seasoned",{1,"Sheriff handed out six special deputy cards Saturday, laminated and everything",1,"Two of them fellas I would not sell a used mower to",1,"Card's got a little gold star printed on it - real pretty"}},
{"s13_law_constable_005","badge",3,"reg=law",{1,"I remember a boy in a ball cap with a star pinned to his shirt",2,"Delbert Ray. Elected constable, district four",1,"Had that man had one hour of training?",3,"A badge from a drawer and his daddy's .38. That's all I knew about his preparation",2,"He was also the only one who showed up at Tanner Road that night"}},
{"s13_law_hand_over_badge_011","badge",2,"reg=law|world=vehicle",{1,"Sheriff says turn in the badge and the car if I'm quitting",2,"You quitting?",1,"I'm asking who he hands 'em to after, that's all I'm asking him"}},
{"s13_law_reserve_signup_025","badge",2,"reg=law|role=law_sheriff,law_sergeant|hour=4,11",{1,"Nine men signed up for reserve deputy this morning",2,"Nine",1,"Two of 'em I have arrested, one of 'em twice",2,"Did you swear 'em in?",1,"I swore in six, I'll let you guess which three I sent home"}},
{"s13_law_sheriff_speech_029","badge",3,"reg=law",{1,"Sheriff stood up on the steps and gave a speech",2,"What'd he say?",1,"Courthouse, then the jail, then the water plant, that's what he said",3,"Water plant ought to be first",1,"I know it, he knows it - he just couldn't say it in that order out loud"}},
{"s13_law_old_sergeant_045","badge",2,"reg=law|role=law_sergeant|tmp=veteran",{1,"Thirty-one years and you're telling me it's over on a Thursday",2,"I'm telling you the phones are out, the courts are shut, and nobody's coming to relieve you",1,"That ain't the same as over, I'll be out front at six"}},
{"s13_law_who_we_answer_046","badge",3,"reg=law|mood=grim",{1,"Who do we answer to now? Truthfully",2,"Sheriff, then the county judge executive - then the governor",1,"Sheriff's here, judge executive's in Florida - Governor's a voice somebody heard on a radio once",3,"So we answer to the sheriff and the sheriff answers to nobody - say that one more time slow"}},
{"s13_law_badge_in_pocket_050","badge",1,"reg=law|mood=grim",{1,"Took the star off the shirt and put it in my front pocket",1,"Not 'cause I'm ashamed of it, 'cause a shiny thing on your chest is a place to aim",1,"Still in the pocket, I check for it like keys"}},
{"s13_law_sheriff_alone_058","badge",2,"reg=law",{1,"Sheriff's been sleeping on the cot in his office since Friday",2,"Somebody ought to tell him to go home",1,"Somebody did, he said his home's got four rooms and no radio in any of 'em"}},
{"s13_law_final_roll_060","badge",3,"reg=law|mood=grim",{1,"Roll call - Mabry",2,"Here",1,"Whitt",3,"Here",1,"Combs - Cundiff - Sowders",1,"Alright - Mabry east half, Whitt west half, I've got the middle and a phone that don't ring"}},
{"ordinary_patch_talk","belonging",2,"reg=club|st=neutral,careful",{1,"Think the patch still means anything?",2,"Depends who's wearing it",1,"That's a convenient answer",2,"Was the answer before all this too"}},
{"ordinary_rescue_praise","belonging",2,"reg=rescue|st=neutral,friendly",{1,"Somebody called me a hero once",2,"What did you say?",1,"Asked them to move their car so we could get the stretcher out",2,"That sounds about right"}},
{"fw_ld4_topics_b_0044","breakdown_talk",2,"reg=civilian,family,worker,rescue",{1,"It's making that noise again",2,"The clicking?",1,"The grinding",2,"Is it smoking?",1,"A little, a lot, okay, definitely smoking"}},
{"fw_ld4_topics_b_0045","breakdown_talk",2,"reg=civilian,family,worker,rescue",{1,"Anyone know about engines?",2,"I know how to turn one on",1,"That's not helpful",2,"It's all I've got, I'm a florist"}},
{"s10_break_june_noise_023","breakdown_talk",2,"reg=civilian,family|mood=funny",{1,"It's making the noise",2,"Which noise?",1,"The one I told you about in June, the one you said was nothing",2,"Well, now it's something"}},
{"s10_break_radiator_volunteers_024","breakdown_talk",3,"reg=family,civilian,worker|hour=10,19|mood=funny",{1,"Radiator's bone dry and the water jug's for drinking",2,"There's one other way to fill a radiator",1,"We're not doing that",3,"I had two cans of pop an hour ago, I'm just saying I'm available"}},
{"s10_break_wrecker_callsign_025","breakdown_talk",2,"reg=military|tmp=seasoned,veteran|day=5,300|mood=grim",{1,"Wrecker, this is {callsign}, request recovery at our location, over",2,"Nothing",1,"Wrecker, {callsign}, anybody with a tow strap on this net, over",2,"Sergeant, the wrecker was the first vehicle we lost",1,"I know that, I like saying it"}},
{"s10_break_lamp_oil_donnie_026","breakdown_talk",3,"reg=raider,outlaw|mood=angry",{1,"Who was supposed to fill the tank?",2,"Donnie",3,"I filled it, out of the can in the barn",1,"The can that says lamp oil on the side?",3,"It burns",1,"It burns in a lamp, Donnie"}},
{"s10_break_listening_battery_027","breakdown_talk",2,"reg=law|day=5,200|mood=sad",{1,"Battery's dead",2,"You left the radio on all night listening to static",1,"I was listening for our people",2,"Well, now our people get to listen to us walking"}},
{"s10_break_tap_the_pump_028","breakdown_talk",2,"reg=worker,club|mood=calm",{1,"Crawl under there and tap the fuel pump with the wrench while I crank it",2,"Tap it how hard?",1,"Like you're waking up a drunk uncle, not like you're mad at him",2,"I'm a little mad at him"}},
{"s10_break_hand_me_flathead_029","breakdown_talk",2,"reg=gang,crime|mood=fear",{1,"Hurry up, man",2,"Hurry up makes it take longer",1,"I keep looking for somebody at the corner",2,"Tell me if you see somebody. Don't turn worrying into a count of who's coming"}},
{"s10_break_prom_date_chain_030","breakdown_talk",2,"reg=club|mood=funny",{1,"Chain snapped",2,"Climb on with me",1,"I'm not riding on the back of your bike like a prom date",2,"Then walk it, prom queen, it's eleven miles",1,"Scoot up"}},
{"s10_break_leave_it_unlocked_031","breakdown_talk",3,"reg=elite|tmp=veteran|mood=calm",{1,"Transmission's gone",2,"Strip it?",1,"Radio, batteries, water, map case, the rest stays",3,"And the truck?",1,"Leave it unlocked, somebody out here can sleep in it"}},
{"s10_break_cemetery_stop_032","breakdown_talk",2,"reg=family|tmp=fresh,seasoned|hour=18,4|mood=sad",{1,"Why'd we stop by the cemetery?",2,"The car stopped here, bug - not me",1,"Are the people in there the good kind of dead?",2,"The best kind, they stay right where you put them"}},
{"s10_break_twenty_miles_mama_033","breakdown_talk",3,"reg=prison|day=3,200|mood=sad",{1,"Truck's done - clutch went",2,"Then I'm walking, my mama's in West Point - twenty miles",3,"Twenty miles of what we just drove past?",2,"Twenty miles of me walking, she made my bail twice, I can walk twenty miles"}},
{"s10_break_pantyhose_belt_034","breakdown_talk",3,"reg=rescue|role=rescue_medical,rescue_firefighter|mood=funny",{1,"Rig's dead - Serpentine belt's in pieces",2,"Patient's holding steady - for now",1,"Anybody got pantyhose? Tie it tight, it'll get us home",3,"I'm wearing mine",1,"Then I'm afraid I'm going to need them, Darla"}},
{"s10_break_spare_checked_in_may_035","breakdown_talk",3,"reg=military|role=soldier,soldier_green,soldier_nco|mood=funny",{1,"Spare's flat too",2,"Who checked the spare?",3,"It was checked, it was full when it got checked",2,"Checked when?",3,"At Knox - in May"}},
{"s10_break_let_it_sleep_036","breakdown_talk",2,"reg=civilian,family,worker|mood=fear",{1,"Don't move, four of 'em walking past the hood",2,"Do they see us?",1,"If they did, they'd be on the glass",2,"My leg's asleep",1,"Let it sleep, everybody in this car be as quiet as that leg"}},
{"s10_break_waiting_on_parts_037","breakdown_talk",3,"reg=worker|mood=funny",{1,"Dump truck's down, we're waiting on parts",2,"There's no parts coming - ever",1,"Then it's the longest break this road crew ever took - on the county's dime",3,"County's not paying us",1,"Then it's a free break - even better"}},
{"s10_break_look_pitiful_038","breakdown_talk",2,"reg=raider|tmp=predator|mood=grim",{1,"Truck's dead - sit on the hood and look pitiful",2,"How pitiful?",1,"Like a man whose truck broke down, first car that stops for you is our new car"}},
{"s10_break_herb_said_please_039","breakdown_talk",2,"reg=family|role=family_elder,family_woman,family_youth|day=5,300|mood=sad",{1,"Come on, old girl - Herb kept you running thirty years",2,"It's the alternator, Aunt June, talking won't do it",1,"Herb talked to her every time she wouldn't start - said please",2,"Did it ever work?",1,"Every time, I just can't say it the way he did"}},
{"s10_break_four_gallons_no_dale_040","breakdown_talk",2,"reg=law|tmp=seasoned,veteran|day=7,200|mood=grim",{1,"Siphon what's left out of Unit 9 into 31",2,"Unit 9 is Dale's car",1,"Unit 9 has four gallons in it and no Dale - get the hose"}},
{"s10_break_five_miles_walking_041","breakdown_talk",3,"reg=civilian,family|tmp=fresh|hour=15,20|mood=fear",{1,"How far to {town}?",2,"Sign said six miles, that was a while back",1,"So five",2,"Five miles, carrying the water, with the sun going down behind us",3,"Then we start now, and we talk while we walk - about anything but that"}},
{"s10_break_page_the_tow_guy_042","breakdown_talk",2,"reg=gang,crime|mood=funny",{1,"My pager still has the tow guy's number in it",2,"So call him",1,"With what, my shoe?",2,"Page him back - put 911 on it, maybe he's bored"}},
{"s10_break_everything_fine_043","breakdown_talk",1,"reg=civilian,worker,club,outlaw|tmp=seasoned|mood=sad",{1,"Oil's fine - water's fine, belts are fine",1,"Everything on you is fine and you still won't go",1,"Heh, know somebody like that"}},
{"s10_break_bottom_of_hill_044","breakdown_talk",3,"reg=military,worker,civilian|tmp=seasoned,veteran|mood=funny",{1,"Top of that hill's two hundred yards, we push it up there and roll it down",2,"Pop the clutch in second?",1,"Second, everybody else runs behind and piles in, nobody gets left on the hill",3,"What if it doesn't catch?",1,"Then we're in a dead truck at the bottom of a hill - same as now, just lower"}},
{"s13_law_dog_call_026","call",2,"reg=law|mood=warm|world=road",{1,"Loose dog complaint out on Wickham's road",2,"You are not serious",1,"Lady's ninety and it's the only number she knows to call - I'm going"}},
{"s13_law_kid_with_gun_030","call",2,"reg=law|tmp=seasoned|world=building",{1,"I once found a boy on Halbert Street with his daddy's deer rifle on the porch",2,"Did you take it off him?",1,"Took it off him in June, I'd have been right",1,"That day I asked whether he knew how to handle it. Told him not to shoot somebody just for coming up the drive",2,"That's not the law",1,"No it ain't"}},
{"s13_law_gun_store_watch_043","call",2,"reg=law|mood=funny",{1,"Yeary's boy wants us to sit on his gun counter overnight",2,"Tell him to empty the counter into his truck and go home",1,"Told him, he says the insurance requires the inventory stay on premises",2,"Insurance - Lord have mercy"}},
{"s13_law_mother_at_desk_052","call",3,"reg=law|mood=sad",{1,"Woman's been at the front counter since ten, wants us to find her son",2,"Where'd she see him last?",1,"Louisville - June the fifth",3,"We can't get to Louisville",1,"I know, I took the description anyway, height, weight, a scar on his knee off a bicycle"}},
{"s13_ksp_wrecker_rotation_008","call",2,"reg=law|mood=funny",{1,"Who's up on the wrecker rotation?",2,"The rotation, you are asking me about the rotation",1,"It's a list, lists are the part of this I can still do right"}},
{"s13_ksp_accident_31w_009","call",3,"reg=law|mood=grim|world=vehicle",{1,"Two-car on 31W at the Tanner Road cut, both drivers gone from the scene",2,"Gone where?",1,"One set of prints out of the ditch walking north - and a child's seat in the Buick, empty",3,"Don't say that last part on the air",1,"I'm saying it 'cause somebody's got to hear it and write it down"}},
{"s13_ksp_funeral_escort_013","call",2,"reg=law|hour=4,11|mood=warm|world=road",{1,"I escorted a funeral this morning, lights on, ten mile an hour, the whole thing",2,"Whose?",1,"Fella I never met, family flagged me down at the Sav Rite and asked me to",1,"So we went slow down Main with the lights on and I blocked the one intersection that's left"}},
{"s13_ksp_hitchhiker_021","call",2,"reg=law|mood=warm",{1,"Picked up a woman walking the shoulder with a suitcase - put her in the front seat",2,"Front seat?",1,"Cage in the back, wasn't about to put a schoolteacher behind a cage"}},
{"s13_ksp_pull_over_family_038","call",2,"reg=law|mood=warm|world=building,rooftop",{1,"Stopped a station wagon doing forty with five people and a mattress on the roof",2,"Cite 'em?",1,"Tightened the rope, told 'em West Point's shut, sent 'em on - that's the job now"}},
{"s13_ksp_church_lot_042","call",2,"reg=law|mood=sad",{1,"Little Bethel's got forty people in the lot asking me where they ought to go",2,"What'd you tell 'em?",1,"The truth, which is I don't know, then I stood there twenty minutes 'cause leaving felt worse"}},
{"s13_ksp_traffic_light_048","call",2,"reg=law|mood=calm",{1,"Light at Main and Halbert's flashing yellow all four ways",2,"That ain't right",1,"It's the most right thing in this town, everybody slows down and looks at each other"}},
{"s13_ksp_donut_shop_054","call",2,"reg=law|mood=warm",{1,"Bakery on Main left the case unlocked with a sign taped to the glass",2,"Saying what?",1,"Take what you need, pay when things are normal",2,"How's the case look?",1,"Empty and wiped down, somebody cleaned the glass on their way out"}},
{"s13_ksp_no_ambulance_057","call",2,"reg=law|mood=fear",{1,"Wreck on the Carver bridge approach, man's pinned and I've got no cutters",2,"There's a truck at Riverside with the jaws on it",1,"No pump operator, no crew, no diesel, I'm asking what I do with my hands right now",2,"Talk to him - hold his hand and talk to him, that's what you've got"}},
{"s13_wire_sergeant_eats_last_041","camp",2,"reg=military|mood=warm",{1,"You ain't eaten since yesterday, Sarge",2,"I'll eat when the posts eat",1,"Posts ate at four, I carried it out myself, both of 'em",2,"... Then hand me one and quit looking at me like that"}},
{"s13_wire_hot_and_still_046","camp",2,"reg=military|world=vehicle",{1,"I remember wire so hot you couldn't touch it bare-handed",2,"Hope you were drinking water",1,"Kept telling the boy at post two to take a break. Proud enough to go down before asking"}},
{"s13_wire_letters_home_047","camp",2,"reg=military|mood=sad|world=vehicle",{1,"Mail truck ain't come since the second",2,"Write 'em anyway, put 'em in the bag",1,"Bag's under the cot with forty letters in it",2,"Then the bag's forty men who still think somebody's coming to get it - leave it be"}},
{"exp_rescue_firstname","care_work",2,"reg=rescue|st=friendly,neutral,careful",{1,"I still tell people my name first, before I ask anything",2,"Me too, half the time I have to say it again",1,"Yeah, they're not hearing you - they're just... scared",2,"Can't blame 'em, I barely heard you just now"}},
{"exp_rescue_cleanblanket","care_work",2,"reg=rescue|st=friendly,neutral,careful",{1,"I miss clean blankets, just opening the cupboard and there's a whole stack",2,"Those scratchy ones?",1,"Yeah, the shitty brown ones, I'd love one of those now",2,"Never thought I'd miss that laundry smell either"}},
{"fw_ld4_topics_a_0050","checkpoint",2,"reg=law,swat",{1,"Papers, please",2,"Papers? There's no papers",1,"Name, then, and where you're headed",2,"Frank Miller, my sister's in Bardstown",1,"Pass, but stay on the road"}},
{"fw_ld4_topics_a_0051","checkpoint",2,"reg=military,elite",{1,"Halt, who goes there?",2,"Civilians, ma'am, three of us",1,"Any bites?",2,"None, ma'am",1,"Roll up your sleeves, one at a time"}},
{"fw_ld4_town_a_0012","checkpoint",2,"reg=military,elite",{1,"Civilians at the barrier, sir",2,"How many?",1,"Dozens, with kids",2,"Check for bites, one at a time, no exceptions",1,"And if one's bitten?",2,"...you know the answer, Corporal"}},
{"fw_ld4_town_a_0013","checkpoint",2,"reg=military,elite",{1,"Checkpoint seven reports, no movement",2,"Copy, stay sharp",1,"They're quiet, sir, too quiet",2,"Quiet is just quiet, don't overthink it"}},
{"s13_ksp_bridge_shut_026","checkpoint",2,"reg=law|mood=angry",{1,"Army's got the bridge and Army don't care what color your uniform is",2,"You tell 'em you're state police?",1,"Told a boy with a rifle I'm a sworn peace officer of the Commonwealth - he said yes sir and did not move"}},
{"s13_mp_no_id_031","checkpoint",3,"reg=military|mood=grim",{1,"He's got no ID on him",2,"Then he don't pass, that's the rule and I didn't write it",3,"Wallet's in a house in Valley Station, Sergeant, the house burnt",2,"Log it, name he gives, description, time, no ID - then turn him around and log that I said so"}},
{"s13_mp_woman_no_name_032","checkpoint",2,"reg=military|mood=sad",{1,"Woman at the gate won't give a name",2,"Ask once more - polite",1,"Asked twice, she says a name's the only thing left that's hers",2,"Put refused in the column and let her sit in the shade - that's an answer too"}},
{"s13_mp_receipt_039","checkpoint",2,"reg=military|tmp=veteran",{1,"Give him a receipt for the rifle",2,"A receipt",1,"Notebook paper, his name, what it is, my name, the date - he'll want it back and he ought to get it"}},
{"s13_mp_trooper_asks_045","checkpoint",2,"reg=military|mood=warm",{1,"A state trooper asked me for a copy of the log",2,"Give him one?",1,"Can't copy a book by hand - read him the names of everybody we turned back and he wrote 'em down",2,"That's two records now",1,"That's two records now, I slept better on it"}},
{"s13_mp_search_car_046","checkpoint",3,"reg=military|role=soldier_nco",{1,"Do we search vehicles?",2,"Look in, don't dig - you're counting people and looking for sick, not going through a suitcase",3,"Orders say search",2,"Orders say search for the sick - read the whole line, Kerns"}},
{"s13_mp_fever_check_047","checkpoint",2,"reg=military",{1,"How do you check for sick with no thermometer?",2,"Back of your hand on the neck, look at the eyes, ask 'em to squeeze your hand",1,"That's not medicine",2,"No, it's what we've got and the medic showed me himself how to do it"}},
{"s13_mp_the_line_moves_049","checkpoint",2,"reg=military|tmp=veteran",{1,"Line's a mile deep and it ain't moved in two hours",2,"Then walk it, water down the line, tell everybody where they stand and how long",1,"They'll be mad",2,"They'll be mad and they'll stay in their cars, mad in a car is what we want"}},
{"s13_mp_kid_asks_050","checkpoint",2,"reg=military|mood=warm",{1,"Little girl asked me if I was a policeman",2,"What'd you say?",1,"Said sort of - Army's version, she asked if I could find her cat, I said no ma'am, she said okay"}},
{"s13_mp_fort_gate_054","checkpoint",2,"reg=military|mood=funny",{1,"Main gate's got civilians four deep asking about the gold",2,"The gold",1,"Every one of 'em, like there's a window where you trade it in for beans"}},
{"s13_mp_thank_you_060","checkpoint",2,"reg=military|mood=warm",{1,"A man thanked me today",2,"For what?",1,"For writing his wife's name down, he said now she's in a book somewhere"}},
{"s13_mp_night_lane_061","checkpoint",2,"reg=military|hour=21,4",{1,"Close the outer lane at dark and put the cones back at the bend",2,"Why the bend?",1,"So a man's already slowed down before he sees a rifle - half of scared is being surprised"}},
{"exp_club_helmet_hair","club_life",2,"reg=club|st=neutral,careful",{1,"Knew a guy who'd stop and comb his hair every time the helmet came off",2,"Was it good hair?",1,"There were about eight hairs, he was very careful with all of them",2,"Leave him alone, that's all he had"}},
{"exp_club_scenicroute","club_life",2,"reg=club|st=neutral,careful",{1,"Remember your little scenic route? Three hours?",2,"Here we go",1,"Same barn - THREE times, and you wouldn't ask anybody",2,"There wasn't anybody to ask!",1,"The woman selling tomatoes!",2,"I forgot about her"}},
{"exp_club_stitching","club_life",2,"reg=club|st=neutral,careful",{1,"Who sewed your old jacket? Wasn't you",2,"Aunt did, wouldn't let me leave till she'd told me about EVERY cousin",1,"You just sat there?",2,"She still had my jacket, and there was pie"}},
{"s13_merc_contract_036","contract",2,"reg=elite|role=mercenary",{1,"I signed for ninety days at four hundred a day",2,"And how many days have you been paid for?",1,"Nineteen, wire went through on the second of July and that was the last of it"}},
{"s13_merc_invoice_037","contract",2,"reg=elite|role=mercenary",{1,"I'm still filling out the time sheet",2,"For who?",1,"For whoever, hours, date, what I did, goes in the folder with the contract",2,"That folder is going to be worth exactly nothing",1,"Probably, it's also the only thing I own that says I ain't a criminal"}},
{"s13_merc_client_dead_038","contract",3,"reg=elite|role=mercenary|mood=angry|world=door",{1,"Where's the client?",2,"In a house up on the ridge with the doors locked - he don't come out",3,"He's alive?",2,"Alive, and he says the bank in Louisville will sort it when things settle - six days running now"}},
{"s13_merc_who_owns_trucks_039","contract",2,"reg=elite|role=mercenary|world=cars",{1,"Whose trucks are these?",2,"Company's",1,"Company's in a city that don't answer a phone - ask me again whose trucks these are"}},
{"s13_merc_quit_040","contract",3,"reg=elite|role=mercenary|world=vehicle",{1,"Ruskin's quitting, says the contract's void if nobody's performing",2,"He ain't wrong on paper",3,"He's got a wife in Georgia",1,"Then he ain't wrong at all - let him take a truck and don't make him say it twice"}},
{"s13_merc_why_stay_041","contract",2,"reg=elite|role=mercenary|mood=grim|world=fence",{1,"So why are you still here?",2,"'Cause there's forty people behind that fence who think I'm the reason they're alive",1,"Are you?",2,"Some nights - ask me at four in the morning and you'll get a different answer out of me"}},
{"s13_merc_hazard_rate_042","contract",2,"reg=elite|role=mercenary",{1,"There's a clause doubles the rate for active hostilities",2,"Is this active hostilities?",1,"There ain't a word in that contract for what this is - I read it twice with a flashlight"}},
{"s13_merc_insurance_043","contract",2,"reg=elite|role=mercenary|mood=grim",{1,"I had a policy through the company - Accidental death, the whole thing",2,"Who's the beneficiary?",1,"My sister in Owensboro, and there's no company and no mail, so it's a paper about a paper"}},
{"s13_merc_paid_in_food_044","contract",2,"reg=elite|role=mercenary|mood=funny",{1,"Church offered to pay us in canned goods and diesel",2,"That ain't money",1,"It's better than money right now, and I'd like it in writing anyhow",2,"You want a preacher to sign a contract for beans",1,"I want somebody's name on something - yeah"}},
{"s13_merc_not_soldiers_045","contract",2,"reg=elite|role=mercenary",{1,"Them Guard boys look at us like we're something",2,"We're employees, that's all a contractor is",1,"Try telling 'em that",2,"I did, kid asked what my rank was, I said I don't have one, he didn't laugh"}},
{"s13_merc_rifle_signed_046","contract",2,"reg=elite|role=mercenary",{1,"Every rifle out there is on a receipt with my signature on it",2,"Signed to who?",1,"A logistics manager named Priddy who I have never met one time in person"}},
{"s13_merc_retainer_cleared_047","contract",2,"reg=elite|role=mercenary",{1,"The retainer cleared, that's the only money that was ever real",2,"How much?",1,"Enough to be here, not enough to leave"}},
{"s13_merc_contempt_048","contract",2,"reg=elite|role=mercenary|mood=sad",{1,"That Delta fella looked at my boots and didn't say a word",2,"So?",1,"So he didn't have to, I know what four hundred a day looks like to a man on sergeant's pay",2,"You reckon he cares?",1,"No, that's what makes it sting"}},
{"s13_merc_termination_049","contract",2,"reg=elite|role=mercenary|mood=funny",{1,"There's a termination for convenience clause in it",2,"Whose convenience?",1,"Theirs, thirty days written notice to the address on page one",2,"What's the address on page one?",1,"A suite number in a building in Louisville, drove past it in June, got a fountain out front"}},
{"s13_merc_last_page_050","contract",1,"reg=elite|role=mercenary|mood=grim|world=fence",{1,"Last page is the signature block, mine's in blue ink, theirs is a stamp",1,"Underneath it says this agreement shall be governed by the laws of the Commonwealth of Kentucky",1,"I read that line out loud to the fence the other night - just to hear how it sounded"}},
{"s13_merc_muster_058","contract",3,"reg=elite|role=mercenary|mood=grim",{1,"Muster, sound off with days on contract and days paid",2,"Ninety signed, nineteen paid",3,"Ninety signed, nineteen paid",1,"Same, alright, that's the meeting, nobody's getting paid and everybody showed up anyway"}},
{"s13_law_tax_bills_007","county",2,"reg=law|role=law_deputy,law_sheriff|tmp=seasoned",{1,"Sheriff's office collects the property tax in Kentucky, we still got a drawer of bills",2,"Burn 'em",1,"Can't, they're county records",2,"Everything's county records, the county's dead - burn the damn bills"}},
{"s13_law_grand_jury_012","court",2,"reg=law|tmp=seasoned",{1,"Grand jury was set to sit the second Tuesday",2,"How many showed?",1,"One - Mrs. Kelso, brought a coffee cake and sat in the box two hours 'cause somebody ought to"}},
{"s13_law_seal_the_door_018","court",2,"reg=law|world=door",{1,"We put a seal on the courthouse door, tape and a signature, like that means a thing",2,"It meant something to the fella who turned around and went home",1,"Yeah, one out of four"}},
{"s13_law_no_charges_054","court",3,"reg=law|world=vehicle",{1,"Caught two boys siphoning gas out of the ambulance",2,"Charge 'em with what? Court's shut",1,"So I took the hose and took their names and told 'em the ambulance is the ambulance",3,"That work?",1,"One of 'em cried, other one asked if we were hiring"}},
{"s13_ksp_no_court_appearance_020","court",2,"reg=law|mood=funny",{1,"I've got twelve citations with court dates in August",2,"August",1,"Every one says appear at nine a.m. at the justice center - I'd love to see who shows"}},
{"fw_ld4_topics_b_0041","crash_talk",2,"reg=civilian,family,worker,rescue",{1,"Everybody out, out, OUT!",2,"My leg, my leg's stuck",1,"Pull, pull, I've got you",2,"Out- I'm out! Oh my God"}},
{"fw_ld4_topics_b_0042","crash_talk",2,"reg=civilian,family,worker,rescue|world=trees",{1,"Was that a tree or a person?",2,"A tree, I think",1,"You think?",2,"It didn't scream, so tree"}},
{"fw_ld4_topics_b_0043","crash_talk",2,"reg=civilian,family,worker,rescue",{1,"I told you to watch the road!",2,"I WAS watching the road!",1,"Then who was watching the deer?",2,"...nobody, apparently"}},
{"s10_crash_walts_glasses_001","crash_talk",3,"reg=civilian,family|tmp=fresh,seasoned|mood=fear",{1,"Is everybody okay? Somebody say something",2,"My glasses - where'd my glasses go?",3,"They're on your face, Walt",2,"Well, then they're cracked",1,"We hit a deer - that was a deer, right?",3,"Deer don't wear sneakers"}},
{"s10_crash_sitting_on_radio_002","crash_talk",3,"reg=military|mood=funny",{1,"Sound off - who's hurt?",2,"Bit my tongue - bad",3,"Radio's under me, I think I'm lying on the radio",1,"Get off the radio, Private, the radio's more fragile than you are"}},
{"s10_crash_got_mail_003","crash_talk",3,"reg=raider,outlaw|tmp=predator,seasoned|mood=funny",{1,"Who puts a brick mailbox that close to a road?",2,"Somebody in nineteen sixty, you found it in nineteen ninety-three",3,"Truck's got the whole mailbox in the grille",1,"Then we got mail - get out and push"}},
{"s10_crash_dispatch_said_go_004","crash_talk",2,"reg=law|day=14,200|mood=sad",{1,"I had it up to ninety on the Riverside road - dispatch said go, and I went",2,"Dispatch has been off the air two weeks",1,"I know that, I heard her anyway - plain as day - go ahead, {unit}",2,"Let me look at your head, sit still for me"}},
{"s10_crash_church_shoe_005","crash_talk",3,"reg=family|tmp=fresh|mood=fear",{1,"Everybody out, out the back, the back door!",2,"Mama, I lost my shoe",1,"We just rolled the van, baby, leave the shoe",2,"It's my church shoe",3,"I got it, I got the church shoe - go, go"}},
{"s10_crash_prom_limo_006","crash_talk",3,"reg=gang|mood=funny",{1,"Whose idea was it to take the limo?",2,"It had a TV in the back",1,"A TV don't help you take a corner",3,"Neither did he"}},
{"s10_crash_billboard_step_007","crash_talk",2,"reg=club|mood=calm",{1,"It stepped out from behind the billboard, I had nowhere to go",2,"You had the whole left lane",1,"Left lane had three more of 'em in it",2,"Then you picked right - can you stand?",1,"Ask me again in a minute"}},
{"s10_crash_bent_rifle_status_008","crash_talk",3,"reg=elite|tmp=veteran|hour=20,5|mood=grim",{1,"Status - sound off",2,"Two is up, nose is broken - breathing fine",3,"Three is up, rifle's bent at the handguard",1,"Take the spare - truck stays, four klicks to the water tower, on foot"}},
{"s10_crash_stuck_horn_009","crash_talk",3,"reg=civilian,worker,family|mood=fear",{1,"Horn's stuck! It won't quit!",2,"Yank the wire under the dash!",1,"Which wire? They're all wires!",3,"Forget the horn, grab the bags - everything for two miles just heard that - go!"}},
{"s10_crash_bridge_no_sign_010","crash_talk",2,"reg=worker|tmp=seasoned|day=5,300|mood=sad",{1,"Twenty-six years driving a rig and I never once put one in a ditch",2,"You didn't put it in the ditch, the bridge did",1,"Bridge was out, I should've seen the bridge was out",2,"Nobody put a sign up, nobody puts up signs anymore"}},
{"s10_crash_transport_bus_keys_011","crash_talk",3,"reg=prison|mood=grim",{1,"Bus hit the guardrail doing sixty, chains held every one of us in the seats",2,"And the guards?",1,"Guards weren't chained... I never tell that part",3,"Who got the keys off 'em?",1,"Little fella in the back row, reached real, real far"}},
{"s10_crash_instead_of_driving_012","crash_talk",3,"reg=civilian,family|tmp=fresh|mood=angry",{1,"You were looking at the map!",2,"You told me to look at the map!",1,"While I drove! Not instead of me driving!",3,"Both of you hush, there's blood on the seat - whose is it?",2,"Mine, I think it's mine"}},
{"s10_crash_upside_down_belt_013","crash_talk",2,"reg=rescue|role=rescue_firefighter,rescue_medical|mood=funny",{1,"Eighteen years I cut people out of wrecks",2,"And what?",1,"Never once thought about how it feels, hanging upside down in the belt, waiting",2,"How does it feel?",1,"Like I owe a lot of folks an apology for taking so long"}},
{"s10_crash_both_asleep_014","crash_talk",2,"reg=military,law|tmp=seasoned,veteran|day=3,200|mood=sad",{1,"Garcia fell asleep at the wheel, thirty hours up - nobody told him to pull over",2,"Nobody could've",1,"I was in the passenger seat, I was asleep too"}},
{"s10_crash_catfish_dash_015","crash_talk",3,"reg=raider|tmp=predator|mood=funny|world=water",{1,"Truck's in the pond",2,"How deep?",1,"Up past the mirrors, there's a catfish flopping on the dashboard",3,"Grab the catfish, day ain't a total loss"}},
{"s10_crash_pink_backpack_016","crash_talk",2,"reg=family,civilian|tmp=fresh,seasoned|day=2,200|mood=sad|world=trees",{1,"I swerved for a little girl in the road, that's how we ended up in the trees",2,"There wasn't a girl",1,"There was - pink backpack, standing right on the line",2,"There was, she just wasn't a little girl anymore"}},
{"s10_crash_clean_cut_017","crash_talk",2,"reg=civilian,worker|tmp=fresh,seasoned|mood=fear",{1,"Cut my arm going out the window - hahaha, real clean cut, look at that",2,"Window glass?",1,"Glass, or that fella who was already lying in the ditch - hard to say, it all went real quick"}},
{"s10_crash_trooper_skid_marks_018","crash_talk",2,"reg=law|role=law_trooper,law_deputy,law_sergeant|mood=funny",{1,"Skid marks start forty feet back, you were doing fifty-five, maybe sixty",2,"Are you working my wreck?",1,"Twenty years of habit, I'd write you a ticket if I had the book",2,"A ticket for what?",1,"Failure to maintain your lane, and scaring me half to death"}},
{"s10_crash_papaw_license_019","crash_talk",3,"reg=family|mood=funny",{1,"Papaw, you don't even have a license",2,"State took it in eighty-nine - state's gone, I figured that made it mine again",3,"You drove clean through the Tillmans' carport",2,"I saw the carport, I just didn't agree with it"}},
{"s10_crash_riverbank_cartons_020","crash_talk",2,"reg=crime,outlaw|mood=funny|world=water",{1,"Forty cartons in the creek",2,"Lay 'em out on the rocks to dry",1,"You can't dry a cigarette, man, they come out tasting like a riverbank",2,"Then we trade 'em to somebody who likes riverbanks"}},
{"s10_crash_ground_on_ceiling_021","crash_talk",1,"reg=civilian,family,worker|tmp=fresh|mood=fear",{1,"Seatbelt, undo the seatbelt - where's the button?",1,"Why is the ground up on the ceiling?",1,"Okay, crawl out the side window - you're okay, you're, you're okay"}},
{"s10_crash_nicest_bunker_022","crash_talk",3,"reg=swat|mood=funny",{1,"Twelve tons of truck lying on its side on the exit ramp",2,"Can we set it back up?",1,"With what? Five of us and a real good attitude?",3,"Then it's a bunker now, nicest bunker on 31W"}},
}
